files.content:
:root {
  color-scheme: dark;
}
* {
  box-sizing: border-box;
}
body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: #1a1c2c;
  color: #fff;
  font-family: "Courier New", monospace;
}
.panel {
  width: min(90vw, 360px);
  background: #29366f;
  border: 4px solid #fff;
  box-shadow: 6px 6px 0 #000;
  padding: 20px;
}
h1 {
  margin: 0 0 16px;
  font-size: 1.2rem;
  text-align: center;
  letter-spacing: 2px;
  text-shadow: 2px 2px 0 #000;
}
label {
  display: block;
  margin: 12px 0 4px;
  font-size: 0.85rem;
  text-transform: uppercase;
}
input,
select,
button {
  width: 100%;
  padding: 8px;
  font: inherit;
  color: #fff;
  background: #111;
  border: 3px solid #fff;
  border-radius: 0;
  box-shadow: 3px 3px 0 #000;
}
input:focus,
select:focus,
button:focus {
  outline: 3px solid #f3d34c;
  outline-offset: 2px;
}
button {
  margin-top: 16px;
  cursor: pointer;
  background: #e43b78;
}
button:active {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0 #000;
}
.formulas {
  margin: 14px 0;
  padding: 8px;
  font-size: 0.7rem;
  line-height: 1.5;
  background: #111;
  border: 2px solid #fff;
}
#result {
  display: block;
  margin-top: 14px;
  padding: 10px;
  font-size: 2rem;
  text-align: center;
  background: #000;
  border: 3px solid #fff;
  box-shadow: inset 3px 3px 0 #444;
}

const form = document.getElementById('converter');
const temperature = document.getElementById('temperature');
const direction = document.getElementById('direction');
const result = document.getElementById('result');

form.addEventListener('submit', (event) => {
  event.preventDefault();

  const raw = temperature.value.trim();
  const value = Number(raw);

  if (raw === '' || !Number.isFinite(value)) {
    result.textContent = 'Error';
    return;
  }

  const converted = direction.value === 'c-to-f'
    ? value * 9 / 5 + 32
    : (value - 32) * 5 / 9;

  result.textContent = converted.toFixed(2);
});
